/**
 * The stroke typeface, and the math that sizes one glyph.
 *
 * How the writing effect works: a letter here is not an outline, it is the
 * path a pen took. Each glyph is a list of strokes, each stroke a list of
 * points in drawing order. To show a finished letter you draw the whole
 * path; to animate it you draw the path from the start up to some length.
 *
 * `typeface.json` is generated by `scripts/build-typeface.mjs` from a
 * single-line SVG font (EMS Allure: the script Allura, traced as pen strokes).
 * Coordinates are font units, 1000 per em, with y pointing down and the
 * origin on the baseline at the left of the glyph's advance box. Letters in a
 * connected script start left of their origin and end past their advance on
 * purpose: that is how they join up with their neighbours.
 */
import data from './typeface.json';

interface RawGlyph {
  /** Advance width: how far the pen moves right before the next letter. */
  adv: number;
  /** Strokes, each a flat list: x0, y0, x1, y1, ... */
  s: number[][];
}

interface TypefaceData {
  name: string;
  upm: number;
  ascent: number;
  descent: number;
  xHeight: number;
  capHeight: number;
  glyphs: Record<string, RawGlyph>;
}

export const typeface = data as unknown as TypefaceData;

/** How far the baseline sits below the top of a glyph box, in ems. Swashes reach a full em up. */
export const BASELINE_EM = 1.0;
/** Glyph box height in ems: room for the tallest flourish above and the deepest below. */
export const BOX_EM = 1.45;

export function glyphFor(character: string): RawGlyph | null {
  return typeface.glyphs[character] ?? null;
}

/** One stroke, sized for a font size. Points are pixels relative to the glyph origin (pen start, baseline). */
export interface ScaledStroke {
  points: number[]; // x0, y0, x1, y1, ...
  length: number; // pixels
}

export interface ScaledGlyph {
  /** Advance width in pixels. */
  advance: number;
  strokes: ScaledStroke[];
  /** Sum of stroke lengths in pixels. */
  totalLength: number;
  /** Sum of stroke lengths in font units. Writing speed is "font units per second". */
  unitLength: number;
}

const cache = new Map<string, ScaledGlyph>();

/** Scales a glyph to a font size (the em), exactly like a normal font would. */
export function scaleGlyph(character: string, glyph: RawGlyph, size: number): ScaledGlyph {
  const cacheKey = `${character}@${size}`;
  const hit = cache.get(cacheKey);
  if (hit) return hit;

  const scale = size / typeface.upm;
  let totalLength = 0;
  const strokes: ScaledStroke[] = glyph.s.map((flat) => {
    const points: number[] = new Array(flat.length);
    let length = 0;
    for (let i = 0; i < flat.length; i += 2) {
      points[i] = flat[i] * scale;
      points[i + 1] = flat[i + 1] * scale;
      if (i > 0) length += Math.hypot(points[i] - points[i - 2], points[i + 1] - points[i - 1]);
    }
    totalLength += length;
    return { points, length };
  });

  const scaled: ScaledGlyph = {
    advance: glyph.adv * scale,
    strokes,
    totalLength,
    unitLength: totalLength / scale,
  };
  cache.set(cacheKey, scaled);
  return scaled;
}
